// Additional, card-specific reading text. The original short explanations remain
// in the catalog; the Russian and English continuations below are shown only
// after choosing “Learn more”. IDs must cover every released fact.
export const detailExpansions: Record<string, readonly [ru: string, en: string]> = {
  'venus-rotation': ['Оборот относительно звёзд не совпадает с промежутком между полуднями на поверхности: за время вращения Венера успевает пройти часть орбиты. Поэтому при сравнении «дня» с годом важно сначала сказать, какой именно день имеется в виду.', 'A turn relative to distant stars is not the same as the interval between noons on the surface: Venus also travels along its orbit while it rotates. When comparing a “day” with a year, we first need to say which kind of day we mean.'],
  'mars-rust': ['Железосодержащие частицы встречаются в марсианской пыли почти повсюду. Когда ветер поднимает эту пыль, красноватым кажется не только грунт, но и сама атмосфера на снимках с поверхности.', 'Iron-bearing particles are widespread in Martian dust. When wind lifts that dust, the reddish color can affect how both the ground and the sky look in pictures taken on the planet.'],
  'earth-ocean': ['На карте кажется, что суши много, но вода соединяет материки единым Мировым океаном. При этом большая часть земной воды солёная: доля океана в запасе воды гораздо выше его доли в площади поверхности.', 'A map can make the land seem dominant, yet water connects the continents in one global ocean. Most of Earth’s water is salty, so the ocean’s share of all water is even greater than its share of surface area.'],
  'jupiter-rotation': ['Быстрое вращение помогает растягивать атмосферные потоки в полосы, заметные даже в телескоп. Юпитер состоит преимущественно из газа и жидкости, поэтому разные широты могут вращаться не совсем с одинаковой скоростью.', 'Rapid rotation helps stretch atmospheric flows into bands visible even through a telescope. Jupiter is mostly gas and fluid, so different latitudes need not rotate at exactly the same rate.'],
  'octopus-hearts': ['Если проследить путь крови, сначала она идёт к жабрам за кислородом, а затем к органам тела. Разделение работы между сердцами помогает поддерживать оба этапа этого круговорота.', 'Trace the blood’s route: it first goes to the gills to take up oxygen, then to the body’s organs. Dividing the work among hearts supports both parts of this circulation.'],
  'octopus-blood': ['Гемоцианин переносит кислород иначе, чем привычный человеку гемоглобин. Цвет зависит от состояния молекулы: насыщенная кислородом кровь осьминога выглядит голубой, а не красной.', 'Hemocyanin carries oxygen differently from the hemoglobin familiar in human blood. Its color depends on the molecule’s state: oxygen-rich octopus blood looks blue rather than red.'],
  'panda-thumb': ['Кость запястья получила новую полезную роль без появления настоящего шестого пальца. Удерживать тонкие стебли важно, потому что красная панда проводит много времени за поеданием бамбука.', 'A wrist bone took on a useful new role without becoming a true sixth finger. Gripping thin stems matters because a red panda spends so much time feeding on bamboo.'],
  'panda-tail': ['Когда панда пробирается по ветвям, хвост помогает ей удерживать равновесие, словно противовес. Во время отдыха она может прикрывать им тело и морду, уменьшая потерю тепла.', 'On branches, the tail helps the panda balance like a counterweight. At rest, the animal can wrap it around its body and face to reduce heat loss.'],
  'metre-light': ['Сначала метр связывали с физическими образцами, которые нужно было хранить и сравнивать. Теперь лаборатории могут воспроизводить единицу через измерения времени и постоянную скорость света, не обращаясь к единственной линейке.', 'The metre was once tied to physical objects that had to be preserved and compared. Laboratories can now reproduce the unit from measurements of time and the fixed speed of light, without relying on one special ruler.'],
  'second-caesium': ['Атомный переход даёт одинаковую физическую опору часам в разных лабораториях. Поэтому определение секунды не зависит от того, как именно движется стрелка конкретных часов или насколько ровно вращается Земля.', 'An atomic transition gives clocks in different laboratories the same physical reference. Defining the second this way does not depend on the motion of one clock’s hands or on Earth rotating with perfect regularity.'],
  'kilogram-planck': ['Раньше эталоном служил конкретный металлический цилиндр, и любое изменение его массы создавало проблему сравнения. Фиксированная константа позволяет воспроизводить килограмм разными экспериментальными методами.', 'A particular metal cylinder once served as the standard, so any change to its mass complicated comparisons. A fixed constant lets laboratories reproduce the kilogram through different experimental methods.'],
  'si-seven': ['Основные единицы описывают разные типы величин, а производные собираются из них по правилам измерения. Например, ускорение выражают в метрах на секунду в квадрате, а силу — через массу и ускорение.', 'Base units describe different kinds of quantity, while derived units combine them according to how a measurement is defined. Acceleration, for example, uses metres per second squared, and force combines mass with acceleration.'],
  'mona-lisa-panel': ['Тополевая доска реагирует на изменения окружающей среды иначе, чем тканый холст. Поэтому материал основы важен не только искусствоведу: он влияет на то, как картину берегут и показывают спустя столетия.', 'A poplar panel responds to its surroundings differently from woven canvas. The support matters beyond art history: it affects how the painting is protected and displayed centuries after it was made.'],
  'great-wave-fuji': ['Если посмотреть в просвет между волнами, маленькую гору легко сначала принять за ещё один гребень. Так Хокусай соединяет близкое бурное море и далёкий спокойный силуэт в одном изображении.', 'Look through the opening between the waves and the tiny mountain is easy to mistake for another crest. Hokusai places the violent nearby sea and a calm distant silhouette in the same image.'],
  'starry-night-canvas': ['Картина изображает ночной вид, но это не фотографическая запись конкретной минуты. Ван Гог работал с цветом и ритмом мазков, превращая небо и свет в часть эмоционального образа.', 'The painting shows a night scene, but it is not a photographic record of one instant. Van Gogh used color and the rhythm of brushstrokes to make the sky and light part of an expressive image.'],
  'matisse-paper': ['Матисс окрашивал листы, вырезал формы и затем переставлял их, подбирая композицию. Вырезанная бумага стала для него самостоятельным способом рисовать цветом, а не просто подготовкой к картине.', 'Matisse colored sheets, cut out shapes, and rearranged them to find a composition. Cut paper became a way of drawing with color in its own right, rather than merely a step toward a painting.'],
  'mercury-year': ['Такой короткий год не означает короткие сутки: вращение Меркурия вокруг оси и обращение вокруг Солнца — разные движения. Если бы вы считали возраст в местных годах, он рос бы гораздо быстрее земного.', 'A short year does not imply a short day: Mercury’s rotation and its journey around the Sun are different motions. Counted in local years, your age would rise far faster than on Earth.'],
  'mercury-solar-day': ['Чтобы Солнце снова оказалось в той же точке неба, Меркурию мало просто повернуться относительно звёзд. Планета за это время продвигается по орбите, и сочетание двух движений растягивает солнечные сутки.', 'For the Sun to return to the same place in the sky, Mercury must do more than turn relative to the stars. The planet also advances along its orbit, and the combination stretches the solar day.'],
  'mercury-not-hottest': ['Меркурий получает сильный солнечный свет, но почти не удерживает тепло без плотной атмосферы. Венера дальше от Солнца, зато её густая атмосфера создаёт мощный парниковый эффект.', 'Mercury receives intense sunlight but has almost no thick atmosphere to retain heat. Venus is farther from the Sun, yet its dense atmosphere produces a powerful greenhouse effect.'],
  'mercury-crater-names': ['Названия помогают исследователям обсуждать одну и ту же область поверхности без путаницы. Международные правила для разных типов объектов задают отдельные темы имён, поэтому карта планеты стала неожиданной культурной энциклопедией.', 'Names let researchers discuss the same surface feature without confusion. International naming rules give different kinds of features their own themes, turning the planet’s map into an unexpected cultural catalogue.'],
  'saturn-density': ['Средняя плотность учитывает всю планету, включая её протяжённую газовую оболочку. Это не значит, что у Сатурна есть твёрдая поверхность, которую можно положить на воду, как деревянный брусок.', 'Average density includes the whole planet and its vast gaseous envelope. It does not mean Saturn has a solid surface that could be placed on water like a block of wood.'],
  'saturn-rings': ['Частицы различаются размером и отражают солнечный свет, из-за чего кольца кажутся яркими. Между ними и внутри колец есть промежутки: это динамическая система, а не цельный диск вокруг планеты.', 'Particles vary in size and reflect sunlight, making the rings look bright. There are gaps between and within the rings: this is a moving system, not one solid disk around the planet.'],
  'saturn-hexagon': ['Шестиугольный контур виден в облаках около полюса и сохраняется при изменении внешнего вида атмосферы. Его стороны образованы движением газа; представить его как вырезанную на планете геометрическую фигуру было бы ошибкой.', 'The hexagonal outline appears in clouds near the pole and persists as the atmosphere changes. Its sides are shaped by moving gas; it is not a geometric figure carved into a solid surface.'],
  'saturn-year': ['Сатурн проходит гораздо более длинный путь вокруг Солнца, чем Земля, и движется по нему медленнее. Человек, проживший тридцать земных лет, встретил бы там лишь примерно один местный Новый год.', 'Saturn travels a much longer path around the Sun than Earth and moves along it more slowly. A person who lived thirty Earth years would have seen only about one local New Year there.'],
  'uranus-sideways': ['В течение части орбиты солнечный свет долго освещает один полюс, пока другой остаётся в продолжительной темноте. Когда Уран перемещается дальше, освещение меняется местами; его времена года совсем не похожи на земные.', 'For part of its orbit, sunlight shines on one pole for a long time while the other remains dark. As Uranus moves farther along, the lighting reverses, creating seasons unlike those on Earth.'],
  'uranus-telescope': ['Другие видимые планеты люди знали с древности без оптических приборов. Уран тоже иногда различим на небе, но его не распознавали как планету, пока наблюдения и расчёты не прояснили его движение.', 'People knew the other visible planets in antiquity without optical instruments. Uranus can sometimes be seen in the sky too, but it was not recognized as a planet until observations clarified its motion.'],
  'uranus-literary-moons': ['Названия вроде Титании и Оберона пришли из пьес Шекспира. Это показывает, что астрономические имена не всегда обязаны античной мифологии: иногда источником становится художественная литература.', 'Names such as Titania and Oberon come from Shakespeare’s plays. Astronomical names need not always come from ancient mythology; literature can supply them too.'],
  'uranus-methane': ['Цвет возникает не потому, что планета покрыта бирюзовой краской или океаном. Газ поглощает одни длины волн солнечного света сильнее других, и до наблюдателя доходит изменённая смесь отражённых цветов.', 'The color does not mean the planet is painted turquoise or covered by an ocean. The gas absorbs some wavelengths of sunlight more strongly than others, changing the mix of reflected light that reaches an observer.'],
  'neptune-math': ['Учёные заметили, что известные тогда планеты не полностью объясняли движение Урана. Они рассчитали, где может находиться ещё одно массивное тело, а наблюдатели направили туда телескоп и обнаружили Нептун.', 'Researchers noticed that the known planets did not fully explain Uranus’s motion. They calculated where another massive body might be, and observers pointed a telescope in that direction to find Neptune.'],
  'neptune-year': ['Его огромная орбита делает календарь непривычным: почти вся человеческая жизнь укладывается в один нептунианский год. Сравнение напоминает, что «год» — не универсальная длительность, а время одного оборота планеты.', 'Its enormous orbit makes a strange calendar: nearly a whole human lifetime fits inside one Neptunian year. The comparison reminds us that a “year” is not a universal duration but the time a planet takes to orbit the Sun.'],
  'neptune-sunlight': ['Свет распространяется очень быстро, но расстояния в Солнечной системе огромны. Сравните это с примерно восьмью минутами от Солнца до Земли: Нептун получает свет значительно позже и в гораздо меньшем количестве.', 'Light moves extremely fast, but Solar System distances are enormous. Compare the journey with roughly eight minutes from the Sun to Earth: Neptune receives sunlight much later and far less intensely.'],
  'triton-backwards': ['Такое обратное движение называют ретроградной орбитой. Оно отличается от привычного направления больших спутников и поддерживает гипотезу, что Тритон сформировался не рядом с Нептуном, а был захвачен позднее.', 'This backward motion is called a retrograde orbit. It differs from the usual direction of large moons and supports the idea that Triton formed elsewhere and was captured by Neptune later.'],
  'elephant-trunk': ['Хобот служит и для обоняния, и для дыхания, и как ловкий хватательный орган. Слон может поднять им крупный предмет, а затем тем же органом осторожно подобрать маленький кусочек пищи.', 'The trunk works for smelling and breathing as well as gripping. An elephant can lift a large object with it and then use the same organ to pick up a small piece of food carefully.'],
  'elephant-ears': ['Тепло переносится кровью из глубины тела к поверхности ушей, где легче отдать его воздуху. Поэтому размер ушей — часть системы охлаждения, особенно полезной крупному животному в жарком климате.', 'Blood carries heat from the body’s interior toward the surface of the ears, where it can pass into the air. The ears are thus part of the cooling system, especially useful to a large animal in a hot climate.'],
  'elephant-teeth': ['Слон пережёвывает грубую растительную пищу, поэтому его большие жевательные зубы сильно изнашиваются. Новые зубы постепенно сдвигаются на место старых, в отличие от обычной для человека смены молочных зубов один раз.', 'Elephants chew coarse plant food, which wears down their large grinding teeth. New teeth move forward to replace old ones, unlike the single childhood change from baby teeth familiar to humans.'],
  'elephant-footpad': ['Снаружи массивная нога кажется жёсткой колонной, но внутри мягкие ткани распределяют давление. Это помогает поддерживать огромный вес и двигаться тише, чем можно ожидать от такого животного.', 'From outside, the massive leg looks like a rigid pillar, but soft tissue inside spreads the pressure. That helps support the elephant’s weight and lets it move more quietly than its size might suggest.'],
  'sloth-algae': ['Шерсть ленивца может стать целой маленькой экосистемой. Зелёный оттенок — не собственный цвет волоса: его создают живущие в шерсти организмы, а среди ветвей такой оттенок затрудняет обнаружение животного.', 'A sloth’s coat can become a tiny ecosystem. The green tint is not the hair’s own color: it comes from organisms living in the fur and can make the animal harder to spot among branches.'],
  'sloth-hair': ['Обычная для зверей укладка направляла бы дождевую воду к животу висящего ленивца. При его постоянной позе обратное направление помогает воде стекать иначе, хотя шерсть выполняет и другие привычные защитные функции.', 'The usual mammal hair direction could channel rain toward the belly of a hanging sloth. With its upside-down posture, the reverse direction helps water drain differently, while the coat still serves other protective functions.'],
  'sloth-swimmer': ['В воде вес тела поддерживается плавучестью, поэтому ограничения наземной ходьбы проявляются по-другому. Сравнивая животных, полезно спрашивать, для какой среды приспособлено их движение, а не называть вид просто медленным.', 'Water supports body weight, so the limitations of walking on land matter differently while swimming. When comparing animals, it helps to ask which environment a movement suits instead of calling a species simply slow.'],
  'sloth-teeth': ['Если зуб постепенно стирается при обработке пищи, непрерывный рост помогает сохранять рабочую поверхность. Такой принцип встречается у разных животных, хотя строение их зубов и рацион могут сильно отличаться.', 'If a tooth wears down while processing food, continued growth helps maintain a working surface. The principle occurs in different animals, even though their teeth and diets may differ greatly.'],
  'cheetah-spots': ['Фотографии боков и хвоста позволяют сравнивать рисунок одного гепарда при повторных наблюдениях. Для охраны вида это полезно: учёным не всегда нужно ловить животное, чтобы понять, кто снова попал в кадр.', 'Photos of a cheetah’s sides and tail can be compared across sightings. That helps conservation work: researchers do not always need to capture an animal to recognize it again.'],
  'cheetah-tail': ['Во время погони добыча быстро меняет направление, и хищнику нужно поворачивать на скорости. Хвост помогает менять положение тела и сохранять баланс, но не заменяет работу лап и позвоночника.', 'Prey changes direction quickly during a chase, so the predator must turn at speed. The tail helps shift the body and maintain balance, working together with the legs and spine.'],
  'cheetah-claws': ['Когти действуют отчасти как шипы на спортивной обуви. Они помогают лапе зацепиться за поверхность при ускорении и поворотах, когда животное пытается не потерять скорость.', 'The claws work a little like studs on sports shoes. They help the paws grip the ground during acceleration and turns, when the animal must avoid losing speed.'],
  'cheetah-chirp': ['Звуки большой кошки не сводятся к грозному рёву. Набор сигналов зависит от вида и ситуации; для матери с детёнышами негромкие контактные звуки куда полезнее далёкого пугающего рыка.', 'A big cat’s sounds are not limited to a dramatic roar. Calls vary by species and situation; for a mother and cubs, quieter contact sounds can be more useful than a far-carrying roar.'],
  'polar-clear-fur': ['Свет, попадая в множество волосков, рассеивается, и вся шуба выглядит светлой. Поэтому цвет отдельного волоса и воспринимаемый цвет шерсти — разные вещи; под шерстью кожа белого медведя тёмная.', 'Light is scattered by the many hairs, making the whole coat appear pale. The color of one hair and the perceived color of the coat are different things; beneath that coat the bear’s skin is dark.'],
  'polar-winter': ['На морском льду медведи продолжают искать добычу и в холодное время года. Самка в берлоге — особый случай: ей нужно безопасное место для рождения и первых месяцев жизни детёнышей.', 'Bears continue searching for prey on sea ice during cold months. A mother in a den is a special case: she needs a sheltered place to give birth and care for young cubs.'],
  'polar-swimming': ['Широкие лапы создают тягу в воде, а задние помогают держать курс. Этот способ движения позволяет преодолевать водные промежутки между льдинами, хотя для медведя такие переходы требуют энергии.', 'Broad front paws generate thrust in water while the hind paws help steer. This lets the bear cross gaps between ice floes, although those journeys still cost energy.'],
  'polar-third-eyelid': ['Мигательная перепонка — дополнительный защитный слой, который можно использовать, не заменяя обычные веки. Она полезна животному, часто встречающему снег, ветер и солёную воду.', 'The nictitating membrane is an extra protective layer used alongside ordinary eyelids. It is useful for an animal that often encounters snow, wind, and salt water.'],
  'web-cern': ['Учёным нужно было находить документы, созданные в разных группах и на разных компьютерах. Идея связывать их гиперссылками решила эту практическую задачу, а позднее оказалась полезной далеко за пределами физики.', 'Scientists needed to find documents made by different teams on different computers. Linking them with hypertext addressed that practical problem, and the approach later proved useful far beyond physics.'],
  'web-first-site': ['Первая страница объясняла, что такое новая система, как разместить собственный документ и где искать другие сведения. Сегодня это привычные функции сайта, но тогда саму идею веб-страниц ещё приходилось представлять пользователям.', 'The first page explained the new system, how to publish a document, and where to find more information. Those are ordinary website functions now, but at the time the idea of a web page itself needed an introduction.'],
  'web-open': ['Решение снять ограничения означало, что разработчикам не нужно было покупать право на использование базовой технологии. Это облегчило появление новых серверов, браузеров и страниц по всему миру.', 'Removing restrictions meant developers did not have to buy permission to use the core technology. That made it easier for new servers, browsers, and pages to appear around the world.'],
  'web-first-browser': ['Программа позволяла не только просматривать связанные документы, но и работать с ними. Позднее название World Wide Web осталось за системой страниц, а конкретные программы для её просмотра стали называться браузерами.', 'The program could do more than view linked documents; it could also work with them. Later, World Wide Web remained the name of the linked-page system, while individual programs used to explore it became browsers.'],
  'qr-two-directions': ['Обычный штрихкод читается как последовательность полос в одном направлении. Квадратная матрица QR-кода использует и строки, и столбцы, поэтому в той же области можно разместить более сложную запись.', 'A conventional barcode is read as stripes along one direction. A QR code’s square matrix uses both rows and columns, allowing a more complex pattern to fit in a compact area.'],
  'qr-rotation': ['Три крупные угловые метки помогают программе обнаружить границы и ориентацию кода на фотографии. Поэтому сканеру не требуется, чтобы пользователь держал телефон строго вертикально.', 'Three large corner markers help software detect the code’s edges and orientation in a photo. The scanner therefore does not require the user to hold a phone perfectly upright.'],
  'qr-damage': ['Помимо данных, изображение содержит информацию для исправления части ошибок считывания. Небольшая потёртость или закрытый участок не всегда мешают восстановить сообщение, хотя возможности исправления не безграничны.', 'Alongside the data, the pattern carries information that can correct some reading errors. A small scratch or obscured area need not make the message unreadable, although the repair capacity has limits.'],
  'qr-versions': ['Версия определяет число маленьких квадратов по каждой стороне матрицы. Выбор зависит от объёма сообщения и уровня исправления ошибок: большой код вмещает больше, но занимает больше места.', 'A version determines how many small squares sit along each side of the matrix. The choice depends on message length and error-correction level: a larger code holds more but needs more space.'],
  'gps-height': ['На такой орбите спутник охватывает сигналом большую область поверхности, чем аппарат на низкой орбите. Приёмник на земле слушает не один спутник, а несколько, сравнивая время прихода их сигналов.', 'At this altitude a satellite can cover a larger part of Earth than one in a low orbit. A receiver on the ground listens to several satellites and compares when their signals arrive.'],
  'gps-two-orbits': ['Спутники постоянно движутся относительно наблюдателя на земле. Поэтому видимые над вами аппараты меняются, хотя система в целом должна продолжать предоставлять достаточно сигналов для определения положения.', 'The satellites move constantly relative to someone on the ground. The craft visible above you therefore change, while the whole system aims to keep enough signals available to determine position.'],
  'gps-six-planes': ['Если бы все спутники двигались по одной линии на небе, многие районы надолго оставались бы без удобного обзора. Разнесённые плоскости помогают распределить аппараты вокруг планеты.', 'If all satellites followed one line across the sky, many places would have poor coverage for long periods. Spreading the orbital planes helps distribute the craft around the planet.'],
  'gps-four-visible': ['Каждый спутник передаёт сведения о времени и своей орбите. Сравнив несколько сигналов, приёмник оценивает расстояния до аппаратов и одновременно уточняет собственную ошибку часов.', 'Each satellite broadcasts timing and orbit information. By comparing several signals, a receiver estimates distances to the craft while also correcting the error in its own clock.'],
  'utf8-variable': ['Английские буквы часто помещаются в один байт, а многие другие символы требуют больше. Поэтому два текста с одинаковым числом видимых знаков могут занимать разный объём памяти.', 'Many basic Latin letters fit in one byte, while other characters often need more. Two texts with the same number of visible characters can therefore take different amounts of storage.'],
  'unicode-formats': ['Символ сначала получает кодовую точку, а формат кодирования определяет, как записать её в памяти. Если выбрать другой UTF-формат, смысл текста не должен меняться, но последовательность байтов будет иной.', 'A character first has a code point, while an encoding format determines how it is stored. Choosing another UTF format should not change the text’s meaning, but it changes the byte sequence.'],
  'utf16-pair': ['Это особенно заметно при работе с некоторыми эмодзи и письменностями за пределами базовой многоязычной плоскости. Две кодовые единицы — всё ещё один кодовый пункт, а видимый знак иногда бывает даже сложнее.', 'This matters for some emoji and scripts outside the basic multilingual plane. Two code units can represent one code point, and a visible character can be more complex still.'],
  'unicode-replacement': ['Если программа не может разобрать входящие байты как ожидаемый текст, она иногда показывает ромбик с вопросительным знаком. Сам символ замены не рассказывает, какие исходные данные потерялись, но предупреждает о проблеме кодировки.', 'If a program cannot decode incoming bytes as expected, it may display a diamond with a question mark. The replacement character cannot recover the lost original data, but it signals an encoding problem.'],
  'impressionism-name': ['Название, задуманное как упрёк, художники и публика со временем приняли как обозначение нового направления. Этот поворот напоминает, что история искусства зависит не только от картин, но и от того, как их обсуждали.', 'A name intended as criticism gradually became the accepted label for a new movement. The shift shows that art history is shaped not only by paintings but also by how people talk about them.'],
  'impressionism-shadows': ['Вместо ровного тёмного пятна художник мог заметить в тени отражённый свет и соседние цвета. Поэтому тень на картине живёт вместе с окружающим воздухом и погодой, а не просто обозначает отсутствие освещения.', 'Rather than painting a flat dark patch, an artist could notice reflected light and nearby colors inside a shadow. The painted shadow then belongs to the surrounding air and weather instead of merely indicating a lack of light.'],
  'impressionism-independence': ['Собственная выставка позволила показать произведения без отбора жюри официального Салона. Публика увидела новый взгляд на современную жизнь и живописную технику, даже если первые отзывы были резкими.', 'An independent exhibition let the artists show work without selection by the official Salon jury. Visitors encountered a new view of modern life and painting technique, even when early reviews were harsh.'],
  'impressionism-pigments': ['Промышленное производство красок меняло набор доступных художнику оттенков. Новые пигменты сами по себе не создали стиль, но дали дополнительные средства для передачи света, воздуха и контрастов.', 'Industrial paint production changed the colors artists could obtain. New pigments did not create the style on their own, but gave painters more tools for representing light, atmosphere, and contrast.'],
  'ukiyo-printing': ['Для многоцветного оттиска требовались отдельные подготовленные доски и точное совмещение цветов. Такая работа объединяла замысел художника с навыками резчика и печатника.', 'A multicolored print required separately prepared blocks and careful alignment of colors. Making one joined the artist’s design with the skills of a carver and a printer.'],
  'ukiyo-calendars': ['Заказные календари были поводом показать мастерство печати и придумать новые сочетания красок. Практическая вещь постепенно стала площадкой для художественных экспериментов.', 'Commissioned calendars gave makers a reason to show off printing skill and try new color combinations. A practical object became a place for artistic experimentation.'],
  'ukiyo-actors': ['Зритель мог узнавать любимого исполнителя по лицу, позе или театральному костюму. Такие изображения работали и как искусство, и как предмет интереса городской публики к сценическим знаменитостям.', 'Viewers could recognize a favorite performer by face, pose, or costume. The images worked both as art and as objects of city audiences’ interest in stage celebrities.'],
  'ukiyo-texts': ['Одна и та же технология постепенно обслуживала разные задачи: распространение письменных текстов, календарей и изображений. Поэтому история гравюры связана и с развитием чтения, и с городской культурой.', 'The same technology gradually served different purposes: circulating written texts, calendars, and images. The history of printmaking is therefore connected to both reading and urban culture.'],
  'seurat-pointillism': ['Вблизи зритель видит отдельные мазки, а на расстоянии они собираются в большие цветовые массы. Эффект зависит от того, где стоять перед картиной: способ письма делает самого зрителя участником восприятия.', 'Up close, a viewer sees separate marks; from farther away, they come together as larger areas of color. Where you stand changes the effect, making the viewer’s perception part of the technique.'],
  'seurat-colour': ['Рядом расположенные цвета воздействуют друг на друга в глазу зрителя. Сёра исследовал этот эффект сознательно, поэтому его метод — не просто терпеливое рисование точек, а продуманная организация цвета.', 'Neighboring colors affect how we perceive each other. Seurat studied that effect deliberately, so his method was not merely patient dot-making but a planned arrangement of color.'],
  'seurat-study': ['Подготовительный этюд позволяет сравнить идею и её окончательное воплощение. Композиция узнаваема, но работа с мазками и цветом ещё не доведена до той системы, которую видно на большом полотне.', 'A preparatory study lets us compare an idea with its final realization. The composition is recognizable, but the brushwork and color have not yet become the system visible in the large painting.'],
  'seurat-island': ['На острове встречались люди разных занятий и возрастов, что давало художнику материал для сложной сцены. При этом картина — тщательно построенная композиция, а не случайный моментальный снимок прогулки.', 'The island brought together people of different ages and occupations, giving the painter material for a complex scene. The picture is carefully composed, however, rather than a random snapshot of a stroll.'],
  'manuscript-handmade': ['До печатного станка каждую страницу приходилось писать отдельно, а украшения могли занимать ещё больше времени. Поэтому книга была результатом длительного труда и стоила несравнимо больше обычной современной печатной книги.', 'Before printing, every page had to be written individually, and decoration could take even longer. A book represented a great deal of labor and was far more costly than an ordinary modern printed volume.'],
  'manuscript-parchment': ['Подготовленная кожа достаточно прочна, чтобы на ней писать и перелистывать страницы. Но размер животного ограничивал размер листа, а создание целой книги требовало много материала и работы.', 'Prepared skin is durable enough to write on and turn as pages. But the size of an animal limited the size of a sheet, and a whole book required much material and labor.'],
  'manuscript-gold': ['Золотой лист или краска усиливали сияние изображения при свете свечей и дневном освещении. Такое оформление также показывало, какие части рукописи заказчик считал особенно значимыми.', 'Gold leaf or paint made an image shine in candlelight and daylight. Such decoration also signaled which parts of a manuscript the patron considered especially important.'],
  'manuscript-stages': ['Сначала нужен был материал для листов, затем текст, изображения и надёжное соединение страниц. Разделение этапов помогает понять, почему даже небольшая рукопись могла быть сложным совместным проектом.', 'First came the material for the leaves, then writing, images, and a durable way to bind pages together. The stages explain why even a small manuscript could be a complex collaborative project.'],
  'rosetta-scripts': ['Греческий язык уже был понятен исследователям, поэтому повторение одного содержания в разных системах письма стало ключом к сравнению. Расшифровка не произошла мгновенно: учёным ещё нужно было выяснить, как знаки передают звуки и слова.', 'Researchers could already read Greek, so the same message in different scripts offered a way to compare them. Decipherment was not immediate: scholars still had to work out how signs represented sounds and words.'],
  'rosetta-decree': ['Обломанные края напоминают, что музейный предмет не равен целому древнему памятнику. Учёные восстанавливают контекст по сохранившимся строкам и другим находкам, а неполнота делает сравнение письменностей особенно интересным.', 'The broken edges remind us that a museum object is not always a complete ancient monument. Scholars reconstruct context from the surviving lines and other finds, while the incomplete text still makes comparison between scripts possible.'],
  'rosetta-date': ['Точная дата связывает надпись с конкретной эпохой. Благодаря этому камень ценен не только как языковой ключ, но и как историческое свидетельство времени Птолемеев.', 'The date ties the inscription to a particular era. The stone is valuable not only as a linguistic key but also as evidence about the Ptolemaic period.'],
  'rosetta-material': ['Гранодиорит — твёрдая магматическая порода, способная долго сохранять высеченные знаки. Название «Розеттский» происходит от места обнаружения, а не от цвета или состава камня.', 'Granodiorite is a hard igneous rock that can preserve carved marks for a long time. “Rosetta” refers to where the stone was found, not to its color or composition.'],
  'sutton-ship': ['Под курганом сохранилось не целое деревянное судно, а след его формы в земле и металлические детали. По расположению этих следов археологи восстановили масштаб корабля и устройство погребения.', 'What survived beneath the mound was not an intact wooden vessel but its impression in the soil and metal fittings. Their positions let archaeologists reconstruct the ship’s scale and the burial’s arrangement.'],
  'sutton-discovery': ['Раскопки начались в 1939 году из интереса к курганам на частной земле. Открытие показало, насколько богатой и связанной с другими регионами была культура раннесредневековой Англии.', 'The excavation began in 1939 with interest in mounds on private land. The discovery revealed how rich and connected to other regions early medieval English culture could be.'],
  'sutton-connections': ['Вещи, попавшие в погребение, могли преодолеть большие расстояния через цепочку обменов. Их наличие не означает, что похороненный человек лично посетил все эти места; оно показывает широту связей и ценность привезённых материалов.', 'Objects in the burial may have traveled through chains of exchange over great distances. They do not prove that the buried person visited every place himself, but they reveal broad connections and the value of imported materials.'],
  'sutton-helmet': ['Крышка была частью кожаного кошелька, но органический материал со временем исчез. Сохранившиеся металлические детали и вставки из камня и стекла позволили восстановить её вид и узнать о вкусе прежних владельцев.', 'The lid once belonged to a leather purse, but the organic material decayed. Surviving metalwork and inlays of stone and glass let conservators reconstruct its appearance and study the craft behind it.'],
  'gutenberg-lines': ['Строки набирали из отдельных металлических литер и выстраивали в две аккуратные колонки. Печатная техника ускорила тиражирование текста, сохранив вид страниц, напоминавший дорогие рукописи.', 'Individual metal types were arranged into lines and two neat columns. Printing made copying the text faster while retaining the appearance of pages familiar from costly manuscripts.'],
  'gutenberg-mainz': ['Печать подвижными литерами позволяла многократно использовать элементы набора для новых страниц. Это издание стало знаменитым примером того, как технология изменила распространение больших текстов в Европе.', 'Movable type let printers reuse pieces of a setting on later pages. This edition became a famous example of how the technology changed the circulation of long texts in Europe.'],
  'gutenberg-catchwords': ['Книгу собирали из отдельных сложенных тетрадей, и переплётчику важно было не перепутать их порядок. Повторённое слово служило простым контрольным знаком: следующая часть должна начинаться именно так.', 'Books were assembled from folded gatherings that a binder had to place in the right order. A repeated word acted as a simple check: the next section should begin with just that word.'],
  'gutenberg-margins': ['Первые печатники обращались к людям, привыкшим видеть рукописные книги. Знакомые поля и колонка делали новую книгу удобной для чтения и оставляли место для пометок и украшений.', 'Early printers served readers accustomed to handwritten books. Familiar margins and columns made the new book easier to read and left room for notes and decoration.'],
  'ur-twenty-squares': ['Игровое поле с розетками и клетками находили в разных местах древнего Ближнего Востока. Сохранившаяся поздняя запись правил помогает понять, как люди могли использовать подобные доски, хотя отдельные варианты игры различались.', 'Boards with rosettes and squares have been found across the ancient Near East. A later surviving rules text helps explain how people may have played on them, although versions of the game could differ.'],
  'ur-rulebook': ['Само игровое поле намного старше записанной инструкции. Это важное различие: дата сохранившегося текста говорит, когда правила записали, а не когда игру впервые придумали.', 'The game board is much older than this written instruction. That distinction matters: the surviving text’s date tells us when rules were recorded, not when the game was first invented.'],
  'ur-ancient-game': ['Шахмат и современных настольных игр ещё не существовало, а люди уже двигали фишки по размеченной доске. Находки показывают, что желание играть по правилам и соревноваться имеет очень долгую историю.', 'Chess and modern board games did not yet exist, yet people were already moving pieces across marked boards. The finds show how long people have enjoyed rules, chance, and competition.'],
  'ur-shell-board': ['Доска была не просто разметкой для ходов: её украшали дорогими материалами и узором. Такой предмет мог демонстрировать вкус и положение владельца наряду с тем, что служил развлечением.', 'The board was more than a surface marked for moves: costly materials and patterns decorated it. Besides being a game, the object could express its owner’s taste and status.'],
  'lewis-island': ['Найти вещь на острове и изготовить её там — разные события. Возможные северные связи фигур объясняют, как предметы могли путешествовать торговыми путями и попадать к владельцам далеко от мастерской.', 'Finding an object on an island is different from making it there. The pieces’ possible northern origin shows how objects could travel through trade routes far from the workshop that produced them.'],
  'lewis-century': ['Мастера придали фигурам человеческие лица, одежду и характерные жесты. Поэтому набор помогает рассмотреть не только историю шахмат, но и детали средневекового костюма и ремесла.', 'The carvers gave the pieces human faces, clothing, and distinctive gestures. The set lets us examine not only chess history but also details of medieval dress and craftsmanship.'],
  'lewis-material': ['Моржовый бивень и зубы кита достаточно плотные для тонкой резьбы. Выбор материала связывает шахматные фигуры с морскими ресурсами и ремеслом северных регионов.', 'Walrus tusk and whale teeth are dense enough for detailed carving. The material connects the chess pieces to marine resources and northern craft traditions.'],
  'lewis-many-sets': ['Если собрать все найденные фигуры как одну партию, одинаковых королей и королев окажется слишком много. Из этого исследователи делают вывод о нескольких комплектах, чьи части оказались вместе.', 'Trying to arrange all the found pieces as one match gives too many kings and queens. That leads researchers to conclude that parts of several sets ended up together.'],
  'baikal-depth': ['Озеро занимает тектоническую впадину, которая уходит глубоко в земную кору. Сравнивать эту глубину с высотой горы можно только аккуратно: здесь меряют расстояние от поверхности воды до дна.', 'The lake fills a tectonic basin that cuts deep into Earth’s crust. Comparing that depth with a mountain’s height requires care: here the measurement runs from the water surface down to the lakebed.'],
  'baikal-age': ['Многие озёра появляются и исчезают по геологическим меркам быстро, а Байкал сохранился миллионы лет. За это время его обитатели развивались в относительно изолированной среде, создавая богатство уникальных видов.', 'Many lakes appear and disappear quickly on geological timescales, while Baikal has persisted for millions of years. Its inhabitants evolved in relative isolation, helping produce a wealth of unusual species.'],
  'baikal-water': ['Объём озера особенно впечатляет потому, что речь об одном водоёме, а не о сумме множества рек. Но «20%» относится к определённой категории запасов пресной воды; без этого уточнения число легко понять неверно.', 'The lake’s volume is striking because it belongs to one body of water rather than many rivers combined. But the “20%” figure concerns a defined category of fresh water; without that qualifier it is easy to misunderstand.'],
  'baikal-endemics': ['Эндемик — не обязательно редкое животное: это вид, естественный ареал которого ограничен определённым местом. Изоляция Байкала позволила таким организмам приспособиться к его особым условиям.', 'An endemic species is not necessarily rare: its natural range is limited to a particular place. Baikal’s isolation let such organisms adapt to the lake’s distinctive conditions.'],
  'canyon-colorado': ['Река работала вместе с поднятием плато, разрушением пород и другими геологическими процессами. Поэтому каньон — результат длительной истории ландшафта, а не одного внезапного потока воды.', 'The river acted alongside uplift of the plateau, weathering, and other geological processes. The canyon is the result of a long landscape history, not one sudden rush of water.'],
  'canyon-layers': ['Пласты на стенах лежат один над другим словно страницы, но между ними бывают большие перерывы во времени. Само ущелье значительно моложе многих пород, которые оно сегодня обнажает.', 'Rock layers stack like pages along the walls, although large gaps in time can separate them. The canyon itself is much younger than many of the rocks it exposes today.'],
  'canyon-depth': ['При взгляде с края трудно оценить расстояние до реки и размер уступов. Перепад высот создаёт несколько природных зон с различными температурами и условиями для растений.', 'From the rim it is hard to judge the distance to the river or the size of the ledges. The elevation change creates several environments with different temperatures and growing conditions.'],
  'canyon-human-traces': ['Люди посещали и населяли район каньона задолго до появления туристических троп. Археологические памятники дополняют историю пород рассказом о жизни, передвижениях и приспособлении человека.', 'People visited and lived in the canyon region long before tourist trails existed. Archaeological sites add evidence of human lives, movement, and adaptation to the story told by the rocks.'],
  'galapagos-distance': ['Животным и растениям было непросто добраться до удалённых островов, а затем их популяции развивались отдельно от материковых. Так удалённость вместе с местными условиями способствовала появлению своеобразной фауны.', 'It was difficult for plants and animals to reach the remote islands; populations that arrived then developed apart from mainland ones. Isolation together with local conditions helped create the islands’ distinctive wildlife.'],
  'galapagos-currents': ['Течения приносят воды с разной температурой и питательными веществами. Их встреча помогает объяснить, почему вокруг сравнительно небольших островов существует такое разнообразие морских организмов.', 'The currents bring water with different temperatures and nutrients. Their meeting helps explain why such a wide range of marine life surrounds relatively small islands.'],
  'galapagos-volcanoes': ['Острова поднялись из океана благодаря вулканизму, а отдельные части архипелага имеют разный возраст. Поэтому условия для заселения и эволюции организмов менялись от острова к острову.', 'The islands rose from the ocean through volcanism, and different parts of the archipelago are different ages. Conditions for colonization and evolution therefore varied from one island to another.'],
  'galapagos-darwin': ['Во время путешествия Дарвин собирал и сравнивал образцы растений и животных. Значение увиденного он осмыслял постепенно: одно посещение не породило готовую теорию в тот же день.', 'Darwin collected and compared plants and animals during his voyage. He worked out the meaning of those observations over time; a single visit did not produce a finished theory that day.'],
  'iguazu-border': ['Две страны охраняют разные части одного и того же природного района. Вода и животные свободно пересекают границу на карте, поэтому сохранение ландшафта требует внимания с обеих сторон.', 'Two countries protect different parts of the same natural region. Water and wildlife move across a border on a map, so preserving the landscape matters on both sides.'],
  'iguazu-width': ['Число описывает всю дугу системы, а не ширину одной струи. Между каскадами встречаются островки и растительность, поэтому вид меняется в зависимости от точки наблюдения и уровня воды.', 'The figure describes the arc of the whole system, not the width of one stream. Islets and vegetation separate the cascades, so the view changes with vantage point and water level.'],
  'iguazu-height': ['Вода разбивается на множество потоков, и брызги поднимаются обратно вверх в виде облака. Высота — лишь одна мера масштаба; на впечатление влияют также ширина системы и расход реки.', 'Water breaks into many streams and spray rises back up in clouds. Height is only one measure of scale; the system’s width and the river’s flow also shape the spectacle.'],
  'iguazu-forest': ['Лес удерживает влажную среду вокруг водопадов и даёт убежище многочисленным видам. Охрана места означает заботу не только о туристической панораме, но и о живой экосистеме.', 'The forest maintains a humid environment around the falls and shelters many species. Protecting the site means caring for a living ecosystem as well as a spectacular tourist view.'],
  'hawaii-two-volcanoes': ['Оба вулкана помогают изучать, как из потоков лавы строится остров. Даже в одном парке их формы и история активности различаются, поэтому вулканический ландшафт не стоит представлять единообразным.', 'Both volcanoes help researchers study how lava builds an island. Their shapes and histories of activity differ even within one park, so a volcanic landscape is not one uniform thing.'],
  'hawaii-island-building': ['После остывания лава становится твёрдой породой, которую затем меняют ветер, вода и живые организмы. Так можно наблюдать переход от нового камня к сложному ландшафту с почвой и растениями.', 'Cooling lava becomes solid rock, then wind, water, and living things change it. The process lets us see a transition from new stone to a landscape with soil and plants.'],
  'mauna-loa-height': ['У вулкана есть подводное основание, невидимое при взгляде с берега. Поэтому высота вершины над морем и полная вертикальная протяжённость вулканического сооружения дают разные числа.', 'The volcano has an underwater base invisible from shore. Its summit elevation above sea level and the total vertical extent of the volcanic structure therefore give different numbers.'],
  'hawaii-fern-forest': ['Лава после застывания постепенно выветривается, и в подходящих влажных местах появляются условия для растений. Соседство леса и вулканов показывает разные стадии развития одной территории.', 'Once lava hardens, weathering gradually changes it, and moist places can support plants. Forest beside volcanoes shows different stages of development within one region.'],
  'ice-floats': ['При замерзании молекулы воды образуют более открытую структуру, чем в жидкости. Это имеет последствия для озёр: лёд оказывается сверху, а под ним может сохраняться жидкая вода для живых организмов.', 'Freezing arranges water molecules in a more open structure than in the liquid. That matters for lakes: ice stays on top while liquid water can remain below for living things.'],
  'water-four-degrees': ['Остывшая до четырёх градусов вода опускается глубже, но при дальнейшем охлаждении становится легче и остаётся ближе к поверхности. Так водоём может покрыться льдом сверху, не промерзая целиком сразу.', 'Water cooled to around four degrees sinks, but as it cools further it becomes less dense and stays nearer the surface. A lake can thus ice over from the top without freezing solid at once.'],
  'water-litre': ['Правило удобно для прикидки массы воды в бутылке или кастрюле. Однако плотность немного меняется при нагреве и охлаждении, а солёная или содержащая примеси вода уже не даёт точно того же результата.', 'The rule is handy for estimating the weight of water in a bottle or pot. Density changes slightly as water warms or cools, though, and salty or impure water will not give exactly the same result.'],
  'iceberg-underwater': ['Лёд плавает, потому что менее плотен, чем окружающая вода, но разница невелика. Поэтому над поверхностью видна лишь небольшая часть, а основная масса скрыта и опасна для судов.', 'Ice floats because it is less dense than the surrounding water, but the difference is modest. Only a small part shows above the surface while most of the mass remains hidden from ships.'],
  'carbon-diamond-graphite': ['В графите атомы устроены слоями, которые легко скользят друг по другу; в алмазе они связаны прочной пространственной сетью. Один и тот же химический состав поэтому может давать совершенно разное поведение материала.', 'Graphite’s atoms form layers that slide over one another, while diamond has a strong three-dimensional network. The same chemical composition can therefore produce very different material behavior.'],
  'carbon-graphene': ['Этот тончайший слой представляет собой один уровень атомов углерода в упорядоченной решётке. Он помогает изучать, как свойства вещества меняются, когда материал становится почти двумерным.', 'This extremely thin sheet has one layer of carbon atoms in an ordered lattice. It helps researchers explore how a substance behaves when the material becomes nearly two-dimensional.'],
  'carbon-filter': ['Особая обработка создаёт в угле множество мелких пор и большую внутреннюю поверхность. На ней могут удерживаться некоторые молекулы из воздуха или воды, хотя один фильтр не удаляет всё подряд.', 'Processing creates many tiny pores and a large inner surface in the carbon. Some molecules from air or water can stick there, although one filter cannot remove everything.'],
  'carbon-fibre': ['Тонкие углеродные нити часто объединяют с полимером в композит. Конструкция может быть лёгкой и жёсткой, но её свойства зависят от направления волокон и способа изготовления.', 'Thin carbon fibers are often combined with a polymer to form a composite. The result can be light and stiff, but its properties depend on fiber direction and how it was made.'],
  'helium-sun': ['Астрономы заметили необычные линии в солнечном свете и связали их с ещё не известным на Земле веществом. Позднее гелий нашли и здесь, подтвердив, что свет дал подсказку о составе далёкой звезды.', 'Astronomers noticed unusual lines in sunlight and connected them to a substance not yet identified on Earth. Helium was later found here too, confirming that light had revealed something about a distant star.'],
  'helium-balloons': ['Воздух выталкивает наполненный гелием шар с силой, зависящей от вытесненного объёма. Чтобы шар действительно взлетел, эта подъёмная сила должна превысить вес оболочки, газа и привязанного груза.', 'Air pushes up on a helium-filled balloon according to the volume it displaces. To rise, that buoyant force must exceed the weight of the envelope, gas, and any attached load.'],
  'helium-unreactive': ['Инертность означает, что гелий при обычных условиях почти не образует химических соединений. В защитной атмосфере это помогает не допускать нежелательных реакций с воздухом при работе с чувствительными материалами.', 'Being inert means helium forms almost no chemical compounds under ordinary conditions. In a protective atmosphere it helps prevent unwanted reactions with air around sensitive materials.'],
  'helium-cooling': ['При очень низких температурах некоторые материалы становятся сверхпроводниками и проводят ток без обычного сопротивления. Жидкий гелий помогает поддерживать нужный холод для мощных магнитов.', 'At very low temperatures some materials become superconductors and carry current without ordinary resistance. Liquid helium helps maintain the cold needed by powerful magnets.'],
  'silicon-crust': ['Большая часть кремния связана с кислородом в минералах, из которых состоят горные породы и песок. Распространённость элемента не означает, что в природе легко найти готовые чистые кристаллы для электроники.', 'Most silicon is bound to oxygen in minerals that make up rocks and sand. An abundant element does not mean that nature provides ready-made pure crystals for electronics.'],
  'silicon-diatoms': ['Микроскопические диатомовые водоросли строят из кремнезёма прочные и причудливо устроенные оболочки. После их гибели такие оболочки могут накапливаться в донных отложениях.', 'Microscopic diatoms build sturdy, intricate shells from silica. After the organisms die, these shells can accumulate in sediments on the bottom of a body of water.'],
  'silicon-chips': ['Примеси вводят в контролируемых количествах, чтобы управлять движением электрических зарядов. Так из одного материала получают области с разными свойствами, необходимые для работы транзисторов.', 'Impurities are added in carefully controlled amounts to manage how electric charges move. One material can then contain regions with different properties needed for transistors to work.'],
  'silicon-silicone': ['Похожее звучание названий легко вводит в заблуждение. Кремний можно найти в составе песка и электронных схем, а силиконовые полимеры используют, например, в уплотнителях и гибких медицинских изделиях.', 'The similar names are easy to confuse. Silicon occurs in sand and electronic circuits, while silicone polymers are used, for example, in sealants and flexible medical products.'],
  'oxygen-air': ['Большую часть сухого воздуха составляет азот, а также присутствуют аргон и другие газы. Поэтому выражение «дышать кислородом» описывает потребность организма, но не точный состав каждого вдоха.', 'Nitrogen makes up most dry air, alongside argon and other gases. “Breathing oxygen” describes what the body needs, not the exact composition of every breath.'],
  'oxygen-water': ['Рыбы получают для дыхания молекулы кислорода, растворённые в воде, через жабры. Атомы кислорода, связанные внутри молекулы H₂O, не являются тем же самым доступным газом.', 'Fish use their gills to take up oxygen molecules dissolved in water. Oxygen atoms bound inside H₂O molecules are not the same readily available gas.'],
  'oxygen-crust': ['Это число относится к массе всей коры, а не к количеству чистого газообразного кислорода в камнях. Многие минералы состоят из кислорода вместе с кремнием, металлами и другими элементами.', 'The figure concerns the crust’s mass, not free oxygen gas trapped in rocks. Many minerals contain oxygen combined with silicon, metals, and other elements.'],
  'oxygen-name': ['История названия напоминает, что научные слова переживают гипотезы, с которыми появились. Даже когда представление о составе кислот изменилось, знакомое имя элемента осталось в употреблении.', 'The name shows how scientific words can outlive the theories that produced them. Even after ideas about acids changed, the familiar name of the element remained in use.'],
  'eye-pupil': ['На фотографиях зрачок выглядит чёрным кружком, но это вход во внутреннюю часть глаза, а не чёрная ткань. При ярком свете радужка сужает отверстие, а в темноте расширяет его.', 'In photos the pupil looks like a black circle, but it is an opening into the eye, not black tissue. The iris narrows it in bright light and widens it in darkness.'],
  'eye-two-lenses': ['Роговица обеспечивает значительную часть преломления, а хрусталик может менять форму для настройки фокуса. Благодаря их совместной работе изображение попадает на сетчатку более чётко.', 'The cornea provides much of the bending of light, while the lens can change shape to adjust focus. Working together, they bring an image more sharply onto the retina.'],
  'eye-electric-signals': ['Светочувствительные клетки реагируют на фотоны и запускают цепочку изменений в сетчатке. По зрительному нерву идут сигналы, которые мозг ещё должен обработать, чтобы возникло зрительное восприятие.', 'Light-sensitive cells respond to photons and start a chain of changes in the retina. Signals travel along the optic nerve, and the brain must still process them to form visual perception.'],
  'eye-brain': ['Мозг объединяет информацию от двух глаз, движения глаз и прежний опыт. Поэтому зрение — активная обработка сигналов, а не пассивная передача готовой картинки по нерву.', 'The brain combines information from both eyes, eye movements, and past experience. Vision is active processing of signals, not a finished picture sent passively along a nerve.'],
  'ear-three-bones': ['Это одни из самых маленьких костей человека, но их расположение имеет большое значение. Они передают движение барабанной перепонки к заполненной жидкостью улитке внутреннего уха.', 'These are among the smallest bones in the human body, yet their arrangement matters greatly. They carry motion from the eardrum toward the fluid-filled cochlea of the inner ear.'],
  'ear-cochlea': ['Форма напоминает раковину улитки, а внутри находится сложная чувствительная система. Волна в жидкости приводит в движение клетки, которые помогают превратить механическое колебание в сигнал для мозга.', 'Its shape resembles a snail shell, while its inside holds an intricate sensory system. Waves in the fluid move cells that help turn mechanical vibration into signals for the brain.'],
  'ear-hair-cells': ['Название связано с тонкими выступами клетки, а не с обычными волосами на коже. Эти клетки особенно важны для слуха, потому что именно они связывают движение жидкости с работой нервной системы.', 'The name refers to tiny projections on a cell, not ordinary hair on skin. These cells are crucial because they connect movement in the inner-ear fluid with activity in the nervous system.'],
  'ear-pitches': ['Разные звуковые частоты сильнее возбуждают разные области чувствительной структуры. Так ухо раскладывает сложный звук на составляющие ещё до того, как мозг распознает речь или музыку.', 'Different sound frequencies stimulate different parts of the sensitive structure most strongly. The ear begins separating a complex sound before the brain recognizes speech or music.'],
  'taste-five': ['Умами часто связывают с продуктами, богатыми глутаматом, например с бульоном. Это отдельная категория вкусовых ощущений, а не просто другое название приятной или солёной еды.', 'Umami is often associated with glutamate-rich foods such as broth. It is a distinct kind of taste sensation, not just another word for pleasant or salty food.'],
  'taste-tongue-map': ['Популярный рисунок делит язык на зоны, будто каждая способна чувствовать только один вкус. На деле клетки, воспринимающие разные вкусовые качества, встречаются в разных участках, поэтому сладкое можно заметить не только кончиком языка.', 'A popular diagram divides the tongue into zones supposedly limited to one taste each. In reality, cells detecting different tastes occur in many areas, so sweetness is not confined to the tongue’s tip.'],
  'taste-aroma': ['Когда нос заложен, знакомое блюдо кажется менее выразительным, хотя рецепторы языка продолжают работать. Мозг соединяет вкусы, запахи и ощущения во рту в единое впечатление о пище.', 'With a blocked nose, familiar food can seem dull even though the tongue’s receptors still work. The brain combines taste, smell, and sensations in the mouth into one impression of a meal.'],
  'taste-chilli': ['Капсаицин активирует рецепторы, связанные с ощущением жара и раздражения. Поэтому перец может казаться «горячим», даже когда он холодный; это ощущение отличается от сладкого или кислого вкуса.', 'Capsaicin activates receptors involved in sensing heat and irritation. A chilli can thus feel “hot” while physically cold; the sensation differs from sweet or sour taste.'],
  'dna-four-letters': ['Порядок оснований образует последовательность, которую клетка может копировать и считывать. Четыре символа не означают четыре простых инструкции: длинные цепочки позволяют хранить огромное разнообразие информации.', 'The order of the bases forms a sequence cells can copy and read. Four symbols do not mean only four simple instructions: long chains can store a vast range of information.'],
  'dna-chromosomes': ['Молекула ДНК очень длинная по сравнению с клеточным ядром, поэтому её упаковка имеет значение. Перед делением клетки хромосомы становятся особенно заметными, когда материал нужно аккуратно распределить между дочерними клетками.', 'A DNA molecule is extremely long compared with the cell nucleus, so packaging matters. Chromosomes become especially visible before cell division, when material must be distributed carefully to daughter cells.'],
  'dna-mitochondria': ['Митохондриальная ДНК намного меньше основного набора в ядре. Это ещё один пример того, что клетка устроена не как один мешок с инструкциями: разные её части выполняют связанные задачи.', 'Mitochondrial DNA is far smaller than the main set in the nucleus. It is another reminder that a cell is not one bag of instructions: its different parts carry out connected jobs.'],
  'dna-billion': ['Основания образуют длинную последовательность, но не каждый её участок кодирует белок. Различать число оснований и число генов важно: это разные способы описать размер и устройство генома.', 'The bases form a long sequence, but not every stretch codes for a protein. The number of bases and the number of genes describe different things about the genome.'],
  'digestion-mouth': ['Жевание увеличивает площадь поверхности пищи, с которой могут работать ферменты. Поэтому пищеварение — цепочка механических и химических процессов, начинающаяся задолго до попадания еды в желудок.', 'Chewing increases the food’s surface area for enzymes to work on. Digestion is a chain of mechanical and chemical processes that begins long before food reaches the stomach.'],
  'digestion-peristalsis': ['Волна сокращений двигает содержимое даже тогда, когда человек не думает о работе пищевода и кишечника. Это координированное движение помогает пище пройти по длинному тракту.', 'A wave of contractions moves material even when we are not thinking about the esophagus or intestines. The coordinated motion helps food travel through a long digestive tract.'],
  'digestion-water': ['После переваривания полезных веществ содержимое ещё содержит много воды. Толстый кишечник возвращает часть этой воды организму, а оставшийся материал постепенно становится плотнее.', 'After nutrients have been processed, the remaining contents still contain much water. The large intestine returns some of it to the body, and the remaining material gradually becomes firmer.'],
  'digestion-parts': ['Крупные молекулы пищи не могут просто перейти в клетки в исходном виде. Ферменты разбирают их на меньшие части, которые затем всасываются и используются организмом для разных нужд.', 'Large food molecules cannot simply enter cells unchanged. Enzymes break them into smaller parts that can be absorbed and used by the body in different ways.'],
};
